DROP TABLE IF EXISTS public.audit_log_v2_2026_05 CASCADE;
DROP TABLE IF EXISTS public.audit_log_v2_2026_06 CASCADE;
DROP TABLE IF EXISTS public.audit_log_v2_2026_11 CASCADE;
DROP TABLE IF EXISTS public.agent_traces_v2_2026_05 CASCADE;
DROP TABLE IF EXISTS public.agent_traces_v2_2026_06 CASCADE;
DROP TABLE IF EXISTS public.agent_traces_v2_2026_11 CASCADE;
DROP TABLE IF EXISTS public.trace_events_v2_2026_05 CASCADE;
DROP TABLE IF EXISTS public.trace_events_v2_2026_06 CASCADE;
DROP TABLE IF EXISTS public.trace_events_v2_2026_11 CASCADE;
DROP TABLE IF EXISTS public.knowledge_graph_health CASCADE;
DROP FUNCTION IF EXISTS internal.set_perf_baseline();
DROP FUNCTION IF EXISTS internal.detect_perf_regressions();
DROP MATERIALIZED VIEW IF EXISTS public.knowledge_graph_health CASCADE;
CREATE TABLE IF NOT EXISTS internal.db_health_samples ( id BIGSERIAL PRIMARY KEY, captured_at TIMESTAMPTZ NOT NULL DEFAULT now(), wal_bytes BIGINT NOT NULL DEFAULT 0, connections_used INT NOT NULL DEFAULT 0, connections_max INT NOT NULL DEFAULT 0, connections_pct NUMERIC(5,2) NOT NULL DEFAULT 0, long_running_count INT NOT NULL DEFAULT 0, top_slow_mean_ms NUMERIC NOT NULL DEFAULT 0, top_slow_preview TEXT );
CREATE TABLE IF NOT EXISTS internal.detector_slo_state ( job_name TEXT PRIMARY KEY, consecutive_failures INT NOT NULL DEFAULT 0, last_alerted_at TIMESTAMPTZ, last_checked_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS internal.index_usage_snapshots ( id BIGSERIAL PRIMARY KEY, captured_at TIMESTAMPTZ NOT NULL DEFAULT now(), schemaname TEXT NOT NULL, relname TEXT NOT NULL, indexrelname TEXT NOT NULL, idx_scan BIGINT NOT NULL, idx_tup_read BIGINT NOT NULL, idx_tup_fetch BIGINT NOT NULL, index_size_bytes BIGINT NOT NULL, table_size_bytes BIGINT NOT NULL, is_unique BOOLEAN NOT NULL, is_primary BOOLEAN NOT NULL, is_partial BOOLEAN NOT NULL );
CREATE TABLE IF NOT EXISTS internal.partitioned_families ( parent_table text PRIMARY KEY, partition_prefix text NOT NULL, retention_days integer NOT NULL CHECK (retention_days >= 1), policy_kind text NOT NULL CHECK (policy_kind IN ('agent_traces','workspace_admin','service_only')), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS internal.query_perf_baseline ( queryid BIGINT PRIMARY KEY, query_sample TEXT NOT NULL, calls BIGINT NOT NULL, total_exec_ms NUMERIC NOT NULL, mean_exec_ms NUMERIC NOT NULL, stddev_exec_ms NUMERIC NOT NULL, rows_returned BIGINT NOT NULL, captured_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS internal.query_perf_snapshots ( id BIGSERIAL PRIMARY KEY, snapshot_at TIMESTAMPTZ NOT NULL DEFAULT now(), queryid BIGINT NOT NULL, query_sample TEXT NOT NULL, calls BIGINT NOT NULL, total_exec_ms NUMERIC NOT NULL, mean_exec_ms NUMERIC NOT NULL, stddev_exec_ms NUMERIC NOT NULL, rows_returned BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS internal.query_stats_snapshots ( id BIGSERIAL PRIMARY KEY, captured_at TIMESTAMPTZ NOT NULL DEFAULT now(), queryid BIGINT NOT NULL, query_sample TEXT NOT NULL, calls BIGINT NOT NULL, total_exec_ms NUMERIC NOT NULL, mean_exec_ms NUMERIC NOT NULL, max_exec_ms NUMERIC NOT NULL, rows_returned BIGINT NOT NULL, shared_blks_hit BIGINT NOT NULL, shared_blks_read BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS internal.table_activity_snapshots ( id BIGSERIAL PRIMARY KEY, captured_at TIMESTAMPTZ NOT NULL DEFAULT now(), schemaname TEXT NOT NULL, relname TEXT NOT NULL, n_tup_ins BIGINT NOT NULL, n_tup_upd BIGINT NOT NULL, n_tup_del BIGINT NOT NULL, n_tup_hot_upd BIGINT NOT NULL, n_live_tup BIGINT NOT NULL, n_dead_tup BIGINT NOT NULL, table_size_bytes BIGINT NOT NULL, indexes_size_bytes BIGINT NOT NULL, last_autovacuum TIMESTAMPTZ, last_autoanalyze TIMESTAMPTZ );
CREATE TABLE IF NOT EXISTS internal.cron_tokens ( name TEXT PRIMARY KEY, token TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), rotated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE OR REPLACE VIEW internal.index_audit_report AS WITH latest AS ( SELECT DISTINCT ON (schemaname, relname, indexrelname) * FROM internal.index_usage_snapshots ORDER BY schemaname, relname, indexrelname, captured_at DESC ), first_seen AS ( SELECT schemaname, relname, indexrelname, min(captured_at) AS first_captured FROM internal.index_usage_snapshots GROUP BY schemaname, relname, indexrelname ) SELECT l.schemaname, l.relname, l.indexrelname, l.idx_scan, pg_size_pretty(l.index_size_bytes) AS index_size, l.index_size_bytes, l.is_unique, l.is_primary, l.is_partial, f.first_captured, EXTRACT(day FROM (now() - f.first_captured))::int AS days_observed, CASE WHEN l.is_primary OR l.is_unique THEN 'KEEP: constraint' WHEN l.is_partial THEN 'REVIEW: partial index (may be intentional)' WHEN l.idx_scan = 0 AND EXTRACT(day FROM (now() - f.first_captured)) >= 30 THEN 'DROP CANDIDATE: unused >=30d' WHEN l.idx_scan < 10 AND EXTRACT(day FROM (now() - f.first_captured)) >= 30 THEN 'REVIEW: rarely used' ELSE 'KEEP: active' END AS recommendation FROM latest l JOIN first_seen f USING (schemaname, relname, indexrelname);
CREATE OR REPLACE VIEW internal.write_amplification_report AS WITH latest_tbl AS ( SELECT DISTINCT ON (schemaname, relname) * FROM internal.table_activity_snapshots ORDER BY schemaname, relname, captured_at DESC ), prev_tbl AS ( SELECT DISTINCT ON (schemaname, relname) * FROM internal.table_activity_snapshots WHERE captured_at < now() - interval '20 hours' ORDER BY schemaname, relname, captured_at DESC ) SELECT l.relname, (l.n_tup_ins + l.n_tup_upd + l.n_tup_del) - COALESCE(p.n_tup_ins + p.n_tup_upd + p.n_tup_del, 0) AS writes_last_24h, pg_size_pretty(l.indexes_size_bytes) AS indexes_size, pg_size_pretty(l.table_size_bytes) AS table_size, ROUND(l.indexes_size_bytes::numeric / NULLIF(l.table_size_bytes, 0), 2) AS index_to_table_ratio, l.n_dead_tup, ROUND(l.n_dead_tup::numeric / NULLIF(l.n_live_tup, 0), 3) AS dead_ratio, CASE WHEN l.n_dead_tup::numeric / NULLIF(l.n_live_tup, 0) > 0.2 THEN 'BLOAT WARNING' WHEN l.indexes_size_bytes > l.table_size_bytes * 2 THEN 'INDEX-HEAVY' ELSE 'OK' END AS status FROM latest_tbl l LEFT JOIN prev_tbl p USING (schemaname, relname);
CREATE MATERIALIZED VIEW public.knowledge_graph_health AS WITH ent AS ( SELECT workspace_id, id, entity_type, updated_at, properties FROM public.knowledge_entities WHERE workspace_id IS NOT NULL ), rel AS ( SELECT ke.workspace_id, kr.source_id, kr.target_id FROM public.knowledge_relations kr JOIN public.knowledge_entities ke ON ke.id = kr.source_id WHERE ke.workspace_id IS NOT NULL ), orphans AS ( SELECT e.workspace_id, 20.0 * (1.0 - COALESCE( (SELECT COUNT(*)::numeric FROM ent e2 WHERE e2.workspace_id = e.workspace_id AND NOT EXISTS (SELECT 1 FROM rel r WHERE r.workspace_id = e2.workspace_id AND (r.source_id = e2.id OR r.target_id = e2.id))) / NULLIF((SELECT COUNT(*) FROM ent e3 WHERE e3.workspace_id = e.workspace_id), 0), 0 )) AS orphans_score FROM ent e GROUP BY e.workspace_id ), broken AS ( SELECT ke.workspace_id, 20.0 * (1.0 - COALESCE( (SELECT COUNT(*)::numeric FROM public.knowledge_relations kr2 JOIN public.knowledge_entities kes ON kes.id = kr2.source_id WHERE kes.workspace_id = ke.workspace_id AND NOT EXISTS (SELECT 1 FROM public.knowledge_entities ket WHERE ket.id = kr2.target_id)) / NULLIF( (SELECT COUNT(*) FROM public.knowledge_relations kr3 JOIN public.knowledge_entities kes3 ON kes3.id = kr3.source_id WHERE kes3.workspace_id = ke.workspace_id), 0 ), 0 )) AS broken_links_score FROM ent ke GROUP BY ke.workspace_id ), freshness AS ( SELECT workspace_id, 20.0 * COALESCE( (COUNT(*) FILTER (WHERE updated_at >= now() - interval '90 days'))::numeric / NULLIF(COUNT(*), 0), 0 ) AS freshness_score FROM ent GROUP BY workspace_id ), coverage AS ( SELECT workspace_id, 20.0 * COALESCE( (COUNT(*) FILTER (WHERE entity_type IS NOT NULL AND entity_type <> '' AND properties ? 'tags'))::numeric / NULLIF(COUNT(*), 0), 0 ) AS coverage_score FROM ent GROUP BY workspace_id ), dedup AS ( SELECT workspace_id, 20.0 * (1.0 - COALESCE( (SELECT COUNT(*)::numeric - COUNT(DISTINCT lower(name) || '::' || entity_type)::numeric FROM public.knowledge_entities e2 WHERE e2.workspace_id = e.workspace_id) / NULLIF((SELECT COUNT(*) FROM public.knowledge_entities e3 WHERE e3.workspace_id = e.workspace_id), 0), 0 )) AS dedup_score FROM ent e GROUP BY e.workspace_id ) SELECT o.workspace_id, ROUND(o.orphans_score::numeric, 1) AS orphans_score, ROUND(b.broken_links_score::numeric, 1) AS broken_links_score, ROUND(d.dedup_score::numeric, 1) AS dedup_score, ROUND(f.freshness_score::numeric, 1) AS freshness_score, ROUND(c.coverage_score::numeric, 1) AS coverage_score, ROUND((o.orphans_score + b.broken_links_score + d.dedup_score + f.freshness_score + c.coverage_score)::numeric, 1) AS total_score, now() AS computed_at FROM orphans o JOIN broken b USING (workspace_id) JOIN dedup d USING (workspace_id) JOIN freshness f USING (workspace_id) JOIN coverage c USING (workspace_id);
CREATE OR REPLACE FUNCTION internal.capture_db_health_sample() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, pg_catalog AS $$DECLARE v_wal BIGINT := 0; v_used INT := 0; v_max INT := 0; v_long INT := 0; v_mean NUMERIC := 0; v_preview TEXT := NULL; BEGIN BEGIN SELECT COALESCE(SUM(size), 0) INTO v_wal FROM pg_ls_waldir(); EXCEPTION WHEN OTHERS THEN v_wal := 0; END; SELECT count(*) INTO v_used FROM pg_stat_activity WHERE datname = current_database(); SELECT setting::int INTO v_max FROM pg_settings WHERE name = 'max_connections'; SELECT count(*) INTO v_long FROM pg_stat_activity WHERE state = 'active' AND datname = current_database() AND now() - query_start > interval '5 minutes'; BEGIN SELECT mean_exec_time, left(query, 200) INTO v_mean, v_preview FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) ORDER BY mean_exec_time DESC LIMIT 1; EXCEPTION WHEN OTHERS THEN v_mean := 0; v_preview := NULL; END; INSERT INTO internal.db_health_samples( wal_bytes, connections_used, connections_max, connections_pct, long_running_count, top_slow_mean_ms, top_slow_preview ) VALUES ( v_wal, v_used, COALESCE(v_max, 0), CASE WHEN COALESCE(v_max,0) > 0 THEN ROUND((v_used::numeric / v_max) * 100, 2) ELSE 0 END, v_long, COALESCE(v_mean, 0), v_preview ); END;$$;
DROP FUNCTION IF EXISTS internal.capture_perf_snapshot();
CREATE OR REPLACE FUNCTION internal.capture_perf_snapshot() RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, extensions AS $$DECLARE v_inserted INTEGER; BEGIN INSERT INTO internal.query_perf_snapshots (queryid, query_sample, calls, total_exec_ms, mean_exec_ms, stddev_exec_ms, rows_returned) SELECT s.queryid, LEFT(s.query, 500), s.calls, s.total_exec_time, s.mean_exec_time, s.stddev_exec_time, s.rows FROM extensions.pg_stat_statements s JOIN pg_database d ON d.oid = s.dbid WHERE d.datname = current_database() AND s.query NOT ILIKE '%pg_stat_statements%' AND s.query NOT ILIKE '%internal.%' AND s.calls >= 5 ORDER BY s.total_exec_time DESC LIMIT 100; GET DIAGNOSTICS v_inserted = ROW_COUNT; DELETE FROM internal.query_perf_snapshots WHERE snapshot_at < now() - INTERVAL '30 days'; RETURN v_inserted; END$$;
CREATE OR REPLACE FUNCTION internal.check_bloat_and_alert() RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, pg_catalog AS $$ DECLARE r RECORD; v_alerts INTEGER := 0; BEGIN FOR r IN SELECT * FROM internal.write_amplification_report WHERE status IN ('BLOAT WARNING', 'INDEX-HEAVY') LOOP IF NOT EXISTS ( SELECT 1 FROM public.security_alerts WHERE category = 'db_bloat' AND metadata->>'relname' = r.relname AND is_resolved = false AND created_at > now() - interval '24 hours' ) THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ( CASE WHEN r.status = 'BLOAT WARNING' THEN 'warning' ELSE 'info' END, 'db_bloat', format('Tabela %s: %s (dead_ratio=%s, index/table=%s)', r.relname, r.status, r.dead_ratio, r.index_to_table_ratio), jsonb_build_object( 'relname', r.relname, 'status', r.status, 'dead_ratio', r.dead_ratio, 'index_to_table_ratio', r.index_to_table_ratio, 'writes_last_24h', r.writes_last_24h, 'indexes_size', r.indexes_size, 'table_size', r.table_size ) ); v_alerts := v_alerts + 1; END IF; END LOOP; RETURN v_alerts; END $$;
CREATE OR REPLACE FUNCTION internal.cleanup_orphan_sessions() RETURNS TABLE(kind text, action text, affected int) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, internal AS $$ DECLARE v_browser_timeout int := 0; v_voice_timeout int := 0; v_browser_purged int := 0; v_voice_purged int := 0; BEGIN WITH updated AS ( UPDATE public.browser_sessions SET status = 'timeout', ended_at = now(), error_message = COALESCE(error_message, 'auto-timeout: no updates for >30min') WHERE status IN ('running','in_progress','pending') AND started_at < now() - interval '30 minutes' AND ended_at IS NULL RETURNING 1 ) SELECT count(*) INTO v_browser_timeout FROM updated; WITH updated AS ( UPDATE public.voice_sessions SET status = 'timeout', ended_at = now(), metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('auto_timeout', true, 'timeout_reason','no updates for >30min') WHERE status IN ('running','in_progress','pending','active') AND started_at < now() - interval '30 minutes' AND ended_at IS NULL RETURNING 1 ) SELECT count(*) INTO v_voice_timeout FROM updated; WITH del AS ( DELETE FROM public.browser_sessions WHERE status IN ('completed','failed','timeout','cancelled') AND COALESCE(ended_at, started_at, created_at) < now() - interval '90 days' RETURNING 1 ) SELECT count(*) INTO v_browser_purged FROM del; WITH del AS ( DELETE FROM public.voice_sessions WHERE status IN ('completed','failed','timeout','cancelled') AND COALESCE(ended_at, started_at, created_at) < now() - interval '90 days' RETURNING 1 ) SELECT count(*) INTO v_voice_purged FROM del; RETURN QUERY VALUES ('browser_sessions','timeout', v_browser_timeout), ('voice_sessions','timeout', v_voice_timeout), ('browser_sessions','purge_90d', v_browser_purged), ('voice_sessions','purge_90d', v_voice_purged); END; $$;
CREATE OR REPLACE FUNCTION internal.cleanup_slack_ephemeral() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, internal AS $$BEGIN DELETE FROM public.slack_event_dedupe WHERE expires_at < now(); DELETE FROM public.slack_user_cache WHERE expires_at < now(); END;$$;
CREATE OR REPLACE FUNCTION internal.detect_health_trend_and_alert() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, pg_temp AS $$ DECLARE v_latest internal.db_health_samples; v_prev_hour internal.db_health_samples; v_last3 internal.db_health_samples[]; v_last2 internal.db_health_samples[]; v_alerts_created int := 0; v_wal_ratio numeric; v_wal_delta bigint; v_all_high boolean; v_all_slow boolean; BEGIN SELECT * INTO v_latest FROM internal.db_health_samples ORDER BY captured_at DESC LIMIT 1; IF v_latest IS NULL THEN RETURN jsonb_build_object('status','no_samples','alerts',0); END IF; SELECT * INTO v_prev_hour FROM internal.db_health_samples WHERE captured_at <= now() - interval '55 minutes' AND captured_at >= now() - interval '75 minutes' ORDER BY captured_at DESC LIMIT 1; IF v_prev_hour IS NOT NULL AND v_prev_hour.wal_bytes > 0 THEN v_wal_ratio := v_latest.wal_bytes::numeric / v_prev_hour.wal_bytes::numeric; v_wal_delta := v_latest.wal_bytes - v_prev_hour.wal_bytes; IF v_wal_ratio >= 1.5 AND v_wal_delta >= 128 * 1024 * 1024 THEN IF NOT EXISTS ( SELECT 1 FROM public.security_alerts WHERE category = 'performance.wal_growth' AND created_at > now() - interval '60 minutes' ) THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ( 'warning', 'performance.wal_growth', format('WAL cresceu %sx em 1h (+%s MB)', round(v_wal_ratio, 2), round(v_wal_delta::numeric / (1024*1024), 1)), jsonb_build_object( 'wal_bytes_now', v_latest.wal_bytes, 'wal_bytes_prev', v_prev_hour.wal_bytes, 'ratio', round(v_wal_ratio, 3), 'delta_mb', round(v_wal_delta::numeric / (1024*1024), 1) ) ); v_alerts_created := v_alerts_created + 1; END IF; END IF; END IF; SELECT array_agg(s ORDER BY s.captured_at DESC) INTO v_last3 FROM ( SELECT * FROM internal.db_health_samples ORDER BY captured_at DESC LIMIT 3 ) s; IF v_last3 IS NOT NULL AND array_length(v_last3, 1) = 3 THEN v_all_high := v_last3[1].connections_pct >= 80 AND v_last3[2].connections_pct >= 80 AND v_last3[3].connections_pct >= 80; IF v_all_high THEN IF NOT EXISTS ( SELECT 1 FROM public.security_alerts WHERE category = 'performance.connections_saturation' AND created_at > now() - interval '60 minutes' ) THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ( 'critical', 'performance.connections_saturation', format('Conexões ≥ 80%% em 3 amostras (última: %s%%)', v_last3[1].connections_pct), jsonb_build_object( 'samples_pct', jsonb_build_array( v_last3[1].connections_pct, v_last3[2].connections_pct, v_last3[3].connections_pct ) ) ); v_alerts_created := v_alerts_created + 1; END IF; END IF; END IF; SELECT array_agg(s ORDER BY s.captured_at DESC) INTO v_last2 FROM ( SELECT * FROM internal.db_health_samples ORDER BY captured_at DESC LIMIT 2 ) s; IF v_last2 IS NOT NULL AND array_length(v_last2, 1) = 2 THEN v_all_slow := v_last2[1].top_slow_mean_ms >= 5000 AND v_last2[2].top_slow_mean_ms >= 5000; IF v_all_slow THEN IF NOT EXISTS ( SELECT 1 FROM public.security_alerts WHERE category = 'performance.slow_query_spike' AND created_at > now() - interval '60 minutes' ) THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ( 'warning', 'performance.slow_query_spike', format('Query mais lenta em %s ms (2 amostras seguidas)', round(v_last2[1].top_slow_mean_ms)), jsonb_build_object( 'samples_mean_ms', jsonb_build_array( v_last2[1].top_slow_mean_ms, v_last2[2].top_slow_mean_ms ) ) ); v_alerts_created := v_alerts_created + 1; END IF; END IF; END IF; RETURN jsonb_build_object( 'status', 'ok', 'alerts_created', v_alerts_created, 'checked_at', now() ); END; $$;
CREATE OR REPLACE FUNCTION internal.detect_perf_regressions() RETURNS TABLE( queryid BIGINT, query_sample TEXT, baseline_mean_ms NUMERIC, current_mean_ms NUMERIC, slowdown_factor NUMERIC, calls_delta BIGINT ) LANGUAGE sql SECURITY DEFINER SET search_path = internal, public, extensions AS $$SELECT b.queryid, b.query_sample, ROUND(b.mean_exec_ms::numeric, 2), ROUND(s.mean_exec_time::numeric, 2), ROUND((s.mean_exec_time / NULLIF(b.mean_exec_ms, 0))::numeric, 2), (s.calls - b.calls) FROM internal.query_perf_baseline b JOIN extensions.pg_stat_statements s ON s.queryid = b.queryid WHERE s.mean_exec_time > b.mean_exec_ms * 2 AND s.mean_exec_time > 5 AND s.calls > b.calls + 10 ORDER BY 5 DESC LIMIT 50;$$;
CREATE OR REPLACE FUNCTION internal.detect_slo_breach_and_alert() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, internal AS $$ DECLARE v_job RECORD; v_state RECORD; v_alerts_created INT := 0; v_jobs_checked INT := 0; v_slo_multiplier INT := 2; v_dedupe_minutes INT := 60; v_min_consecutive INT := 2; v_expected_interval_secs INT; v_slo_ok BOOLEAN; BEGIN FOR v_job IN SELECT j.jobname AS job_name, j.schedule, j.active, ( SELECT MAX(d.start_time) FROM cron.job_run_details d WHERE d.jobid = j.jobid ) AS last_run_at, ( SELECT d.status FROM cron.job_run_details d WHERE d.jobid = j.jobid ORDER BY d.start_time DESC LIMIT 1 ) AS last_status FROM cron.job j WHERE j.jobname IN ( 'detect-health-trend-every-15min', 'smoke-test-health-alerts-every-6h', 'smoke-test-wal-every-6h', 'smoke-test-conn-every-6h' ) LOOP v_jobs_checked := v_jobs_checked + 1; v_expected_interval_secs := CASE WHEN v_job.schedule LIKE '%*/15%' THEN 15 * 60 WHEN v_job.schedule LIKE '%*/6%' THEN 6 * 3600 ELSE 3600 END; v_slo_ok := v_job.active AND v_job.last_run_at IS NOT NULL AND EXTRACT(EPOCH FROM (now() - v_job.last_run_at)) <= v_expected_interval_secs * v_slo_multiplier AND COALESCE(v_job.last_status, 'unknown') = 'succeeded'; INSERT INTO internal.detector_slo_state (job_name, consecutive_failures, last_checked_at, updated_at) VALUES ( v_job.job_name, CASE WHEN v_slo_ok THEN 0 ELSE 1 END, now(), now() ) ON CONFLICT (job_name) DO UPDATE SET consecutive_failures = CASE WHEN v_slo_ok THEN 0 ELSE internal.detector_slo_state.consecutive_failures + 1 END, last_checked_at = now(), updated_at = now() RETURNING * INTO v_state; IF NOT v_slo_ok AND v_state.consecutive_failures >= v_min_consecutive AND (v_state.last_alerted_at IS NULL OR v_state.last_alerted_at < now() - (v_dedupe_minutes || ' minutes')::interval) THEN INSERT INTO public.security_alerts ( severity, category, message, metadata, created_at ) VALUES ( 'critical', 'performance.detector_slo', format('Detector "%s" fora do SLO por %s checagens consecutivas', v_job.job_name, v_state.consecutive_failures), jsonb_build_object( 'job_name', v_job.job_name, 'schedule', v_job.schedule, 'active', v_job.active, 'last_run_at', v_job.last_run_at, 'last_status', v_job.last_status, 'consecutive_failures', v_state.consecutive_failures, 'expected_interval_secs', v_expected_interval_secs, 'slo_multiplier', v_slo_multiplier ), now() ); UPDATE internal.detector_slo_state SET last_alerted_at = now() WHERE job_name = v_job.job_name; v_alerts_created := v_alerts_created + 1; END IF; END LOOP; RETURN jsonb_build_object( 'jobs_checked', v_jobs_checked, 'alerts_created', v_alerts_created, 'checked_at', now() ); END; $$;
CREATE OR REPLACE FUNCTION internal.drop_old_partitions(p_retention_days integer DEFAULT NULL) RETURNS TABLE(dropped_partition text, month_end timestamp with time zone) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'internal', 'pg_temp' AS $function$ DECLARE r record; v_cutoff timestamptz; v_end_ts timestamptz; BEGIN FOR r IN SELECT nc.nspname AS schema, cc.relname AS partition, pg_get_expr(cc.relpartbound, cc.oid) AS bounds, f.retention_days FROM pg_inherits i JOIN pg_class parent ON parent.oid=i.inhparent JOIN pg_class cc ON cc.oid=i.inhrelid JOIN pg_namespace nc ON nc.oid=cc.relnamespace JOIN internal.partitioned_families f ON f.parent_table = parent.relname LOOP v_cutoff := date_trunc('month', now() - make_interval(days => COALESCE(p_retention_days, r.retention_days))); v_end_ts := (regexp_match(r.bounds, $re$TO \('([^']+)'\)$re$))[1]::timestamptz; IF v_end_ts IS NOT NULL AND v_end_ts <= v_cutoff THEN EXECUTE format('DROP TABLE %I.%I', r.schema, r.partition); dropped_partition := r.partition; month_end := v_end_ts; RETURN NEXT; END IF; END LOOP; END; $function$;
CREATE OR REPLACE FUNCTION internal.ensure_monthly_partitions(p_months_ahead integer DEFAULT 12) RETURNS TABLE(created_partition text) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'internal', 'pg_temp' AS $function$ DECLARE f record; v_month_start timestamptz; v_month_end timestamptz; v_partition_name text; v_offset int; v_has_workspace boolean; v_has_agent boolean; v_has_user boolean; BEGIN FOR f IN SELECT * FROM internal.partitioned_families ORDER BY parent_table LOOP FOR v_offset IN -3..GREATEST(p_months_ahead, 6) LOOP v_month_start := date_trunc('month', now() + make_interval(months => v_offset)); v_month_end := v_month_start + interval '1 month'; v_partition_name := format('%s_%s', f.partition_prefix, to_char(v_month_start, 'YYYY_MM')); IF NOT EXISTS ( SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=v_partition_name ) THEN EXECUTE format( 'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.%I FOR VALUES FROM (%L) TO (%L)', v_partition_name, f.parent_table, v_month_start, v_month_end ); EXECUTE format( 'ALTER TABLE public.%I SET ( autovacuum_vacuum_scale_factor = 0.05, autovacuum_analyze_scale_factor = 0.01, autovacuum_vacuum_insert_scale_factor = 0.05, fillfactor = 100)', v_partition_name ); created_partition := v_partition_name; RETURN NEXT; END IF; EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_partition_name); EXECUTE format('GRANT ALL ON public.%I TO service_role', v_partition_name); SELECT bool_or(column_name='workspace_id'), bool_or(column_name='agent_id'), bool_or(column_name='user_id') INTO v_has_workspace, v_has_agent, v_has_user FROM information_schema.columns WHERE table_schema='public' AND table_name=v_partition_name; IF f.policy_kind='agent_traces' AND v_has_user AND v_has_agent THEN EXECUTE format('GRANT SELECT, INSERT ON public.%I TO authenticated', v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "Users can see their own traces" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "Users can see their own traces" ON public.%I FOR SELECT USING (user_id = (SELECT auth.uid())) $p$, v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "Admins only" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "Admins only" ON public.%I FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = %I.agent_id AND public.is_workspace_admin((SELECT auth.uid()), a.workspace_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = %I.agent_id AND public.is_workspace_admin((SELECT auth.uid()), a.workspace_id))) $p$, v_partition_name, v_partition_name, v_partition_name); ELSIF f.policy_kind='workspace_admin' AND v_has_workspace THEN EXECUTE format('GRANT SELECT, INSERT ON public.%I TO authenticated', v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "Admins only" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "Admins only" ON public.%I FOR ALL TO authenticated USING (public.is_workspace_admin((SELECT auth.uid()), workspace_id)) WITH CHECK (public.is_workspace_admin((SELECT auth.uid()), workspace_id)) $p$, v_partition_name); ELSIF f.policy_kind='service_only' THEN EXECUTE format('REVOKE ALL ON public.%I FROM authenticated, anon', v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "service only" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "service only" ON public.%I FOR ALL TO service_role USING (true) WITH CHECK (true) $p$, v_partition_name); END IF; END LOOP; END LOOP; END; $function$;
CREATE OR REPLACE FUNCTION internal.prune_db_health_samples() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = internal, pg_catalog AS $$DELETE FROM internal.db_health_samples WHERE captured_at < now() - interval '30 days';$$;
CREATE OR REPLACE FUNCTION internal.prune_perf_snapshots() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = internal, pg_catalog AS $$DELETE FROM internal.index_usage_snapshots WHERE captured_at < now() - interval '90 days'; DELETE FROM internal.query_stats_snapshots WHERE captured_at < now() - interval '90 days'; DELETE FROM internal.table_activity_snapshots WHERE captured_at < now() - interval '90 days';$$;
CREATE OR REPLACE FUNCTION internal.prune_wal_snapshots() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = internal, public AS $$DELETE FROM internal.wal_snapshots WHERE captured_at < now() - INTERVAL '30 days';$$;
CREATE OR REPLACE FUNCTION internal.purge_crm_cadence_runs(_days integer DEFAULT 90) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_catalog' AS $$DECLARE v_count integer; BEGIN DELETE FROM public.crm_cadence_runs WHERE created_at < now() - make_interval(days => GREATEST(_days, 1)); GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END;$$;
CREATE OR REPLACE FUNCTION internal.purge_telemetry() RETURNS TABLE(table_name text, deleted_rows integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_catalog' AS $function$ DECLARE v_count integer; BEGIN DELETE FROM public.webhook_delivery_logs WHERE created_at < now() - interval '30 days'; GET DIAGNOSTICS v_count = ROW_COUNT; table_name := 'webhook_delivery_logs'; deleted_rows := v_count; RETURN NEXT; DELETE FROM public.security_events WHERE created_at < now() - interval '180 days'; GET DIAGNOSTICS v_count = ROW_COUNT; table_name := 'security_events'; deleted_rows := v_count; RETURN NEXT; DELETE FROM public.cron_schedule_executions WHERE created_at < now() - interval '30 days'; GET DIAGNOSTICS v_count = ROW_COUNT; table_name := 'cron_schedule_executions'; deleted_rows := v_count; RETURN NEXT; DELETE FROM public.queue_items WHERE (status = 'completed' AND created_at < now() - interval '7 days') OR (status = 'failed' AND created_at < now() - interval '30 days') OR (status = 'dead_letter' AND created_at < now() - interval '90 days'); GET DIAGNOSTICS v_count = ROW_COUNT; table_name := 'queue_items'; deleted_rows := v_count; RETURN NEXT; END; $function$;
CREATE OR REPLACE FUNCTION internal.rotate_cron_token(_name TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public AS $$BEGIN UPDATE internal.cron_tokens SET token = encode(gen_random_bytes(32), 'hex'), rotated_at = now() WHERE name = _name; IF NOT FOUND THEN RAISE EXCEPTION 'Token de cron desconhecido: %', _name; END IF; END;$$;
CREATE OR REPLACE FUNCTION internal.sample_rollback_stats() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, pg_catalog AS $$ DECLARE v_commit BIGINT; v_rollback BIGINT; v_deadlocks BIGINT; v_prev_rollback BIGINT; v_prev_time TIMESTAMPTZ; v_delta BIGINT; v_minutes NUMERIC; v_rate NUMERIC; BEGIN SELECT xact_commit, xact_rollback, deadlocks INTO v_commit, v_rollback, v_deadlocks FROM pg_stat_database WHERE datname = current_database(); INSERT INTO internal.rollback_snapshots (xact_commit, xact_rollback, deadlocks) VALUES (v_commit, v_rollback, v_deadlocks); SELECT xact_rollback, captured_at INTO v_prev_rollback, v_prev_time FROM internal.rollback_snapshots WHERE captured_at < now() - INTERVAL '30 seconds' ORDER BY captured_at DESC LIMIT 1; IF v_prev_rollback IS NOT NULL THEN v_delta := v_rollback - v_prev_rollback; v_minutes := GREATEST(EXTRACT(EPOCH FROM (now() - v_prev_time)) / 60.0, 0.01); v_rate := v_delta / v_minutes; IF v_rate > 10 THEN INSERT INTO public.security_alerts (severity, category, title, description, metadata) VALUES ( CASE WHEN v_rate > 50 THEN 'critical' WHEN v_rate > 25 THEN 'high' ELSE 'medium' END, 'database_health', 'Rollback rate elevado', format('Taxa de rollbacks: %.2f/min (delta %s em %.2f min)', v_rate, v_delta, v_minutes), jsonb_build_object('rate_per_min', v_rate, 'delta', v_delta, 'window_minutes', v_minutes) ) ON CONFLICT DO NOTHING; END IF; END IF; DELETE FROM internal.rollback_snapshots WHERE captured_at < now() - INTERVAL '7 days'; END; $$;
CREATE OR REPLACE FUNCTION internal.sample_wal_stats() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, pg_catalog AS $$DECLARE v_current_lsn pg_lsn; v_current_bytes BIGINT; v_last RECORD; v_delta_bytes BIGINT; v_delta_seconds NUMERIC; v_bytes_per_min NUMERIC; v_severity TEXT; BEGIN v_current_lsn := pg_current_wal_lsn(); v_current_bytes := (v_current_lsn - '0/0'::pg_lsn); SELECT captured_at, wal_bytes_total INTO v_last FROM internal.wal_snapshots ORDER BY captured_at DESC LIMIT 1; IF v_last.captured_at IS NULL THEN INSERT INTO internal.wal_snapshots (wal_lsn, wal_bytes_total) VALUES (v_current_lsn, v_current_bytes); RETURN; END IF; v_delta_bytes := v_current_bytes - v_last.wal_bytes_total; v_delta_seconds := EXTRACT(EPOCH FROM (now() - v_last.captured_at)); INSERT INTO internal.wal_snapshots (wal_lsn, wal_bytes_total, bytes_since_last, seconds_since_last) VALUES (v_current_lsn, v_current_bytes, v_delta_bytes, v_delta_seconds); IF v_delta_seconds > 0 THEN v_bytes_per_min := (v_delta_bytes::numeric / v_delta_seconds) * 60; v_severity := CASE WHEN v_bytes_per_min > 500 * 1024 * 1024 THEN 'critical' WHEN v_bytes_per_min > 200 * 1024 * 1024 THEN 'high' WHEN v_bytes_per_min > 50 * 1024 * 1024 THEN 'medium' ELSE NULL END; IF v_severity IS NOT NULL THEN INSERT INTO public.security_alerts (severity, category, title, description, metadata, resolved) VALUES ( v_severity, 'database_health', 'Alta geração de WAL detectada', format('Geração de WAL em %s MB/min excede limite %s.', round(v_bytes_per_min / (1024*1024), 2), v_severity), jsonb_build_object( 'bytes_per_min', v_bytes_per_min, 'delta_bytes', v_delta_bytes, 'delta_seconds', v_delta_seconds, 'current_lsn', v_current_lsn::text ), false ); END IF; END IF; END;$$;
CREATE OR REPLACE FUNCTION internal.set_perf_baseline() RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, extensions AS $$DECLARE v_count INTEGER; BEGIN TRUNCATE internal.query_perf_baseline; INSERT INTO internal.query_perf_baseline (queryid, query_sample, calls, total_exec_ms, mean_exec_ms, stddev_exec_ms, rows_returned) SELECT s.queryid, LEFT(s.query, 500), s.calls, s.total_exec_time, s.mean_exec_time, s.stddev_exec_time, s.rows FROM extensions.pg_stat_statements s JOIN pg_database d ON d.oid = s.dbid WHERE d.datname = current_database() AND s.query NOT ILIKE '%pg_stat_statements%' AND s.query NOT ILIKE '%internal.%' AND s.calls >= 10 ORDER BY s.total_exec_time DESC LIMIT 200; GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END$$;
CREATE OR REPLACE FUNCTION internal.slack_cleanup_dedupe() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, internal AS $$BEGIN DELETE FROM public.slack_event_dedupe WHERE expires_at < now(); DELETE FROM public.slack_user_cache WHERE expires_at < now() - INTERVAL '7 days'; DELETE FROM public.slack_dispatch_dlq WHERE resolved_at IS NOT NULL AND resolved_at < now() - INTERVAL '30 days'; END;$$;
CREATE OR REPLACE FUNCTION internal.smoke_test_connections_saturation() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, pg_catalog AS $$ DECLARE v_run_id uuid := gen_random_uuid(); v_marker text; v_now timestamptz := now(); v_alert_id uuid; v_result jsonb; BEGIN v_marker := '__SMOKE_CONN__' || v_run_id::text; INSERT INTO internal.db_health_samples (captured_at, wal_bytes, connections_pct, top_slow_mean_ms, top_slow_preview) VALUES (v_now - interval '10 minutes', 50 * 1024 * 1024, 85, 0, v_marker), (v_now - interval '5 minutes', 50 * 1024 * 1024, 87, 0, v_marker), (v_now, 50 * 1024 * 1024, 90, 0, v_marker); IF to_regprocedure('internal.detect_health_trend_and_alert()') IS NULL THEN RAISE EXCEPTION 'detector ausente'; END IF; PERFORM internal.detect_health_trend_and_alert(); SELECT id INTO v_alert_id FROM public.security_alerts WHERE category = 'performance.connections_saturation' AND created_at >= v_now - interval '1 minute' ORDER BY created_at DESC LIMIT 1; IF v_alert_id IS NULL THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', 'Smoke Connections falhou: detector não gerou connections_saturation', jsonb_build_object('run_id', v_run_id, 'marker', v_marker)); v_result := jsonb_build_object('ok', false, 'reason', 'no_alert'); ELSE UPDATE public.security_alerts SET is_resolved = true, resolved_at = now(), metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('smoke_run', v_run_id) WHERE id = v_alert_id; INSERT INTO public.security_alerts (severity, category, message, metadata, is_resolved, resolved_at) VALUES ('info', 'performance.smoke_test', 'Smoke Connections OK', jsonb_build_object('run_id', v_run_id, 'validated_alert_id', v_alert_id), true, now()); v_result := jsonb_build_object('ok', true, 'alert_id', v_alert_id); END IF; DELETE FROM internal.db_health_samples WHERE top_slow_preview = v_marker; RETURN v_result; EXCEPTION WHEN OTHERS THEN DELETE FROM internal.db_health_samples WHERE top_slow_preview = v_marker; INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', 'Smoke Connections crashou: ' || SQLERRM, jsonb_build_object('run_id', v_run_id)); RETURN jsonb_build_object('ok', false, 'error', SQLERRM); END; $$;
CREATE OR REPLACE FUNCTION internal.smoke_test_health_alerts() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, pg_temp AS $$ DECLARE v_run_id uuid := gen_random_uuid(); v_marker text; v_started timestamptz := clock_timestamp(); v_detector_ok boolean; v_cron_active boolean; v_alert_id uuid; v_latency_ms integer; BEGIN v_marker := '__SMOKE_TEST__' || v_run_id::text; v_detector_ok := to_regprocedure('internal.detect_health_trend_and_alert()') IS NOT NULL; IF NOT v_detector_ok THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', 'Smoke test falhou: função detect_health_trend_and_alert ausente', jsonb_build_object('smoke_run_id', v_run_id, 'reason', 'detector_missing')); RETURN jsonb_build_object('status','fail','reason','detector_missing','smoke_run_id',v_run_id); END IF; SELECT COALESCE(bool_or(active), false) INTO v_cron_active FROM cron.job WHERE jobname = 'detect-health-trend-every-15min'; IF NOT v_cron_active THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', 'Smoke test falhou: cron detect-health-trend-every-15min inativo ou ausente', jsonb_build_object('smoke_run_id', v_run_id, 'reason', 'cron_inactive')); RETURN jsonb_build_object('status','fail','reason','cron_inactive','smoke_run_id',v_run_id); END IF; INSERT INTO internal.db_health_samples (captured_at, wal_bytes, connections_used, connections_max, connections_pct, long_running_count, top_slow_mean_ms, top_slow_preview) VALUES (now() - interval '10 seconds', 0, 0, 100, 0, 0, 9999, v_marker), (now(), 0, 0, 100, 0, 0, 9999, v_marker); PERFORM internal.detect_health_trend_and_alert(); SELECT id INTO v_alert_id FROM public.security_alerts WHERE category = 'performance.slow_query_spike' AND created_at > v_started - interval '2 seconds' ORDER BY created_at DESC LIMIT 1; v_latency_ms := extract(milliseconds FROM (clock_timestamp() - v_started))::integer; IF v_alert_id IS NULL THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', format('Smoke test: regra slow_query_spike não disparou (latency %s ms)', v_latency_ms), jsonb_build_object( 'smoke_run_id', v_run_id, 'reason', 'no_alert', 'latency_ms', v_latency_ms, 'hint', 'pode ser dedupe de 60min contra alerta real recente' )); ELSE INSERT INTO public.security_alerts (severity, category, message, metadata, is_resolved, resolved_at) VALUES ('info', 'performance.smoke_test', format('Smoke test OK: alerta gerado em %s ms', v_latency_ms), jsonb_build_object( 'smoke_run_id', v_run_id, 'latency_ms', v_latency_ms, 'validated_alert_id', v_alert_id ), true, now()); UPDATE public.security_alerts SET is_resolved = true, resolved_at = now(), metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('smoke_run_id', v_run_id, 'auto_resolved_by', 'smoke_test') WHERE id = v_alert_id; END IF; DELETE FROM internal.db_health_samples WHERE top_slow_preview = v_marker; RETURN jsonb_build_object( 'status', CASE WHEN v_alert_id IS NULL THEN 'fail' ELSE 'ok' END, 'smoke_run_id', v_run_id, 'latency_ms', v_latency_ms, 'alert_id', v_alert_id ); EXCEPTION WHEN OTHERS THEN BEGIN DELETE FROM internal.db_health_samples WHERE top_slow_preview = v_marker; EXCEPTION WHEN OTHERS THEN NULL; END; INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', 'Smoke test falhou com exceção: ' || SQLERRM, jsonb_build_object('smoke_run_id', v_run_id, 'sqlstate', SQLSTATE)); RETURN jsonb_build_object('status','error','smoke_run_id',v_run_id,'error',SQLERRM); END; $$;
CREATE OR REPLACE FUNCTION internal.smoke_test_wal_growth() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, pg_catalog AS $$ DECLARE v_run_id uuid := gen_random_uuid(); v_marker text; v_now timestamptz := now(); v_alert_id uuid; v_result jsonb; BEGIN v_marker := '__SMOKE_WAL__' || v_run_id::text; INSERT INTO internal.db_health_samples (captured_at, wal_bytes, connections_pct, top_slow_mean_ms, top_slow_preview) VALUES (v_now - interval '62 minutes', 100 * 1024 * 1024, 10, 0, v_marker), (v_now, 356 * 1024 * 1024, 10, 0, v_marker); IF to_regprocedure('internal.detect_health_trend_and_alert()') IS NULL THEN RAISE EXCEPTION 'detector ausente'; END IF; PERFORM internal.detect_health_trend_and_alert(); SELECT id INTO v_alert_id FROM public.security_alerts WHERE category = 'performance.wal_growth' AND created_at >= v_now - interval '1 minute' ORDER BY created_at DESC LIMIT 1; IF v_alert_id IS NULL THEN INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', 'Smoke WAL falhou: detector não gerou wal_growth', jsonb_build_object('run_id', v_run_id, 'marker', v_marker)); v_result := jsonb_build_object('ok', false, 'reason', 'no_alert'); ELSE UPDATE public.security_alerts SET is_resolved = true, resolved_at = now(), metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('smoke_run', v_run_id) WHERE id = v_alert_id; INSERT INTO public.security_alerts (severity, category, message, metadata, is_resolved, resolved_at) VALUES ('info', 'performance.smoke_test', 'Smoke WAL OK', jsonb_build_object('run_id', v_run_id, 'validated_alert_id', v_alert_id), true, now()); v_result := jsonb_build_object('ok', true, 'alert_id', v_alert_id); END IF; DELETE FROM internal.db_health_samples WHERE top_slow_preview = v_marker; RETURN v_result; EXCEPTION WHEN OTHERS THEN DELETE FROM internal.db_health_samples WHERE top_slow_preview = v_marker; INSERT INTO public.security_alerts (severity, category, message, metadata) VALUES ('critical', 'performance.smoke_test', 'Smoke WAL crashou: ' || SQLERRM, jsonb_build_object('run_id', v_run_id)); RETURN jsonb_build_object('ok', false, 'error', SQLERRM); END; $$;
CREATE OR REPLACE FUNCTION internal.test_partition_automation() RETURNS TABLE(test_name text, passed boolean, details text) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, internal AS $$ DECLARE v_test_month date; v_partition_name text; v_rls_enabled boolean; v_policy_count int; v_grant_count int; v_parent text; BEGIN v_test_month := date_trunc('month', now() + interval '12 months')::date; PERFORM internal.ensure_monthly_partitions(); FOR v_parent IN SELECT unnest(ARRAY['agent_traces', 'audit_log_v2', 'trace_events_v2']) LOOP v_partition_name := v_parent || '_' || to_char(v_test_month, 'YYYY_MM'); test_name := format('[%s] partição %s existe', v_parent, v_partition_name); passed := EXISTS( SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = v_partition_name ); details := CASE WHEN passed THEN 'OK' ELSE 'FALTANDO' END; RETURN NEXT; IF NOT passed THEN CONTINUE; END IF; SELECT c.relrowsecurity INTO v_rls_enabled FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = v_partition_name; test_name := format('[%s] RLS habilitado em %s', v_parent, v_partition_name); passed := COALESCE(v_rls_enabled, false); details := CASE WHEN passed THEN 'RLS ON' ELSE 'RLS OFF - VAZAMENTO!' END; RETURN NEXT; SELECT count(*) INTO v_policy_count FROM pg_policies WHERE schemaname = 'public' AND tablename = v_partition_name; test_name := format('[%s] políticas em %s', v_parent, v_partition_name); passed := v_policy_count >= 1; details := format('%s políticas', v_policy_count); RETURN NEXT; SELECT count(*) INTO v_grant_count FROM information_schema.role_table_grants WHERE table_schema = 'public' AND table_name = v_partition_name AND grantee = 'service_role'; test_name := format('[%s] grants service_role em %s', v_parent, v_partition_name); passed := v_grant_count >= 1; details := format('%s grants', v_grant_count); RETURN NEXT; END LOOP; END; $$;
CREATE OR REPLACE FUNCTION public.get_knowledge_graph_health(p_workspace_id UUID) RETURNS TABLE ( workspace_id UUID, orphans_score NUMERIC, broken_links_score NUMERIC, dedup_score NUMERIC, freshness_score NUMERIC, coverage_score NUMERIC, total_score NUMERIC, computed_at TIMESTAMPTZ ) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$SELECT h.workspace_id, h.orphans_score, h.broken_links_score, h.dedup_score, h.freshness_score, h.coverage_score, h.total_score, h.computed_at FROM public.knowledge_graph_health h WHERE h.workspace_id = p_workspace_id AND EXISTS ( SELECT 1 FROM public.workspace_members wm WHERE wm.workspace_id = p_workspace_id AND wm.user_id = auth.uid() )$$;
CREATE OR REPLACE FUNCTION internal.check_partition_health() RETURNS TABLE(parent_table text, missing_partition text, severity text) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'internal', 'pg_temp' AS $function$DECLARE f record; v_next_month timestamptz; v_partition_name text; BEGIN FOR f IN SELECT * FROM internal.partitioned_families ORDER BY 1 LOOP v_next_month := date_trunc('month', now() + interval '1 month'); v_partition_name := format('%s_%s', f.partition_prefix, to_char(v_next_month, 'YYYY_MM')); IF NOT EXISTS ( SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = v_partition_name ) THEN PERFORM internal.ensure_monthly_partitions(); IF NOT EXISTS ( SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = v_partition_name ) THEN parent_table := f.parent_table; missing_partition := v_partition_name; severity := 'critical'; INSERT INTO public.security_alerts(severity, category, message, metadata) VALUES ( 'critical', 'partition_missing', format('A partição %s da tabela %s não pôde ser criada automaticamente.', v_partition_name, f.parent_table), jsonb_build_object('parent', f.parent_table, 'partition', v_partition_name) ); RETURN NEXT; END IF; END IF; END LOOP; END;$function$;
CREATE TABLE IF NOT EXISTS public.audit_log_v2_2026_05 PARTITION OF public.audit_log_v2 FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE IF NOT EXISTS public.audit_log_v2_2026_06 PARTITION OF public.audit_log_v2 FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE IF NOT EXISTS public.trace_events_v2_2026_05 PARTITION OF public.trace_events_v2 FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE IF NOT EXISTS public.trace_events_v2_2026_06 PARTITION OF public.trace_events_v2 FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
