DROP FUNCTION IF EXISTS internal.capture_perf_snapshot();
CREATE OR REPLACE FUNCTION internal.capture_perf_snapshot() RETURNS TABLE(kind TEXT, rows_captured BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, extensions, pg_catalog AS $$ DECLARE v_idx BIGINT; v_q BIGINT; v_t BIGINT; BEGIN INSERT INTO internal.index_usage_snapshots (schemaname, relname, indexrelname, idx_scan, idx_tup_read, idx_tup_fetch, index_size_bytes, table_size_bytes, is_unique, is_primary, is_partial) SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, s.idx_tup_read, s.idx_tup_fetch, pg_relation_size(s.indexrelid), pg_relation_size(s.relid), i.indisunique, i.indisprimary, (i.indpred IS NOT NULL) FROM pg_stat_user_indexes s JOIN pg_index i ON i.indexrelid = s.indexrelid WHERE s.schemaname = 'public'; GET DIAGNOSTICS v_idx = ROW_COUNT; INSERT INTO internal.query_stats_snapshots (queryid, query_sample, calls, total_exec_ms, mean_exec_ms, max_exec_ms, rows_returned, shared_blks_hit, shared_blks_read) SELECT queryid, substring(query, 1, 500), calls, total_exec_time, mean_exec_time, max_exec_time, rows, shared_blks_hit, shared_blks_read FROM pg_stat_statements WHERE queryid IS NOT NULL ORDER BY total_exec_time DESC LIMIT 100; GET DIAGNOSTICS v_q = ROW_COUNT; INSERT INTO internal.table_activity_snapshots (schemaname, relname, n_tup_ins, n_tup_upd, n_tup_del, n_tup_hot_upd, n_live_tup, n_dead_tup, table_size_bytes, indexes_size_bytes, last_autovacuum, last_autoanalyze) SELECT s.schemaname, s.relname, s.n_tup_ins, s.n_tup_upd, s.n_tup_del, s.n_tup_hot_upd, s.n_live_tup, s.n_dead_tup, pg_relation_size(s.relid), pg_indexes_size(s.relid), s.last_autovacuum, s.last_autoanalyze FROM pg_stat_user_tables s WHERE s.schemaname = 'public'; GET DIAGNOSTICS v_t = ROW_COUNT; RETURN QUERY VALUES ('indexes', v_idx), ('queries', v_q), ('tables', v_t); END $$;
DO $outer$BEGIN IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN BEGIN PERFORM cron.unschedule(jobname) FROM cron.job WHERE jobname IN ('capture-perf-snapshot','check-db-bloat','prune-perf-snapshots'); EXCEPTION WHEN OTHERS THEN NULL; END; PERFORM cron.schedule('capture-perf-snapshot', '30 3 * * *', $$SELECT internal.capture_perf_snapshot();$$); PERFORM cron.schedule('check-db-bloat', '45 3 * * *', $$SELECT internal.check_bloat_and_alert();$$); PERFORM cron.schedule('prune-perf-snapshots', '0 4 * * 0', $$SELECT internal.prune_perf_snapshots();$$); END IF; END$outer$;
DO $$BEGIN PERFORM internal.capture_perf_snapshot(); EXCEPTION WHEN OTHERS THEN NULL; END$$;
