DO $$BEGIN IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN PERFORM cron.unschedule('sample-wal-stats') WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='sample-wal-stats'); PERFORM cron.schedule( 'sample-wal-stats', '* * * * *', $CRON$SELECT internal.sample_wal_stats();$CRON$ ); PERFORM cron.unschedule('prune-wal-snapshots') WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='prune-wal-snapshots'); PERFORM cron.schedule( 'prune-wal-snapshots', '17 3 * * *', $CRON$SELECT internal.prune_wal_snapshots();$CRON$ ); END IF; END$$;
