CREATE OR REPLACE FUNCTION public.get_db_health_timeseries(_hours INT DEFAULT 24) RETURNS TABLE ( captured_at TIMESTAMPTZ, wal_bytes BIGINT, connections_used INT, connections_max INT, connections_pct NUMERIC, long_running_count INT, top_slow_mean_ms NUMERIC, top_slow_preview TEXT ) LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public, internal, pg_catalog AS $$BEGIN IF NOT public.is_workspace_admin(auth.uid()) THEN RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT s.captured_at, s.wal_bytes, s.connections_used, s.connections_max, s.connections_pct, s.long_running_count, s.top_slow_mean_ms, s.top_slow_preview FROM internal.db_health_samples s WHERE s.captured_at >= now() - make_interval(hours => GREATEST(1, LEAST(_hours, 168))) ORDER BY s.captured_at ASC LIMIT 2016; END;$$;
DO $$BEGIN IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'capture-db-health-every-5min') THEN PERFORM cron.unschedule('capture-db-health-every-5min'); END IF; PERFORM cron.schedule( 'capture-db-health-every-5min', '*/5 * * * *', 'SELECT internal.capture_db_health_sample();' ); END IF; END;$$;
DO $$BEGIN IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'prune-db-health-samples-daily') THEN PERFORM cron.unschedule('prune-db-health-samples-daily'); END IF; PERFORM cron.schedule( 'prune-db-health-samples-daily', '20 3 * * *', 'SELECT internal.prune_db_health_samples();' ); END IF; END;$$;
SELECT internal.capture_db_health_sample();
